import { Suspense, useCallback, useEffect, useMemo, useRef, useState } from "react";
import Spline from "@splinetool/react-spline";
import type { Application, SPEObject } from "@splinetool/runtime";

import { useAudioAnalyser } from "@/hooks/use-audio-analyser";

interface OrbProps {
  className?: string;
}

const Orb = ({ className = "" }: OrbProps) => {
  const splineAppRef = useRef<Application | null>(null);
  const reactiveObjectsRef = useRef<SPEObject[]>([]);
  const baseScaleRef = useRef(new Map<string, { x: number; y: number; z: number }>());
  const baseRotationRef = useRef(new Map<string, { x: number; y: number; z: number }>());
  const basePositionRef = useRef(new Map<string, { x: number; y: number; z: number }>());
  const baseVariableRef = useRef<{ y_position: number; top_sharp: number }>({
    y_position: 0,
    top_sharp: 0,
  });
  const lastVariablesRef = useRef<{ y_position: number; top_sharp: number }>({
    y_position: 0,
    top_sharp: 0,
  });
  const bassHistoryRef = useRef<number[]>([]);
  const trebleHistoryRef = useRef<number[]>([]);
  const hasVariableTargetsRef = useRef(false);
  const bassEnergyRef = useRef(0);
  const trebleEnergyRef = useRef(0);
  const frameRef = useRef<number>();
  const [objectsVersion, setObjectsVersion] = useState(0);
  const [hasReactiveTargets, setHasReactiveTargets] = useState(false);
  const [isSplineReady, setIsSplineReady] = useState(false);
  const [availableObjects, setAvailableObjects] = useState<string[]>([]);

  const analyserOptions = useMemo(
    () => ({
      fftSize: 1024,
      smoothingTimeConstant: 0.85,
      minDecibels: -80,
      maxDecibels: -10,
      loop: true,
      initialVolume: 0.85,
    }),
    []
  );

  const {
    analyser,
    status: audioStatus,
    error: audioError,
    isPlaying,
    currentTime,
    duration,
    togglePlayback,
    load,
    setVolume,
    cleanup: cleanupAudio,
  } = useAudioAnalyser("/songs/amaya.mp3", analyserOptions);

  useEffect(() => {
    load().catch(() => undefined);
    setVolume(0.85);
  }, [load, setVolume]);

  const handleTogglePlayback = useCallback(() => {
    load()
      .then(() => {
        togglePlayback();
      })
      .catch(() => undefined);
  }, [load, togglePlayback]);

  const recordBaseState = useCallback((object: SPEObject) => {
    const safeScale = {
      x: Math.abs(object.scale.x) < 0.0001 ? 1 : object.scale.x,
      y: Math.abs(object.scale.y) < 0.0001 ? 1 : object.scale.y,
      z: Math.abs(object.scale.z) < 0.0001 ? 1 : object.scale.z,
    };

    baseScaleRef.current.set(object.uuid, safeScale);
    baseRotationRef.current.set(object.uuid, { ...object.rotation });
    basePositionRef.current.set(object.uuid, { ...object.position });
  }, []);

  const registerReactiveObjects = useCallback((spline: Application) => {
    const allObjects = spline.getAllObjects();

    baseScaleRef.current.clear();
    baseRotationRef.current.clear();
    basePositionRef.current.clear();
    reactiveObjectsRef.current = [];

    const isCylinder = (object: SPEObject) => {
      const name = object.name?.toLowerCase() ?? "";
      return name.includes("cylinder");
    };

    const seen = new Set<string>();

    const registerCollection = (collection: SPEObject[]) => {
      collection.forEach((object) => {
        if (seen.has(object.uuid)) {
          return;
        }

        seen.add(object.uuid);
        recordBaseState(object);
        reactiveObjectsRef.current.push(object);
      });
    };

    registerCollection(allObjects.filter(isCylinder));

    if (reactiveObjectsRef.current.length === 0) {
      registerCollection(allObjects.filter((object) => (object.name?.toLowerCase() ?? "").includes("group")));
    }

    if (reactiveObjectsRef.current.length === 0) {
      registerCollection(allObjects.filter((object) => object.type === "Mesh").slice(0, 6));
    }

    if (reactiveObjectsRef.current.length === 0) {
      registerCollection(allObjects.slice(0, 6));
    }

    if (reactiveObjectsRef.current.length === 0) {
      console.warn("[Orb] No Spline objects registered for animation.");
    } else {
      console.table(
        reactiveObjectsRef.current.map((object) => ({
          name: object.name || "<untitled>",
          id: object.uuid,
          type: object.type,
          scale: { ...object.scale },
        }))
      );
    }

    setHasReactiveTargets(reactiveObjectsRef.current.length > 0);
    setObjectsVersion((version) => version + 1);
  }, [recordBaseState]);

  const handleSplineLoad = useCallback((spline: Application) => {
    splineAppRef.current = spline;
    if (import.meta.env.DEV) {
      (window as typeof window & { __splineApp?: Application }).__splineApp = spline;
    }

    try {
      const variables = spline.getVariables?.();
      if (variables) {
        const yPosition = Number(variables.y_position);
        const topSharp = Number(variables.top_sharp);

        if (!Number.isNaN(yPosition) && !Number.isNaN(topSharp)) {
          baseVariableRef.current = {
            y_position: yPosition,
            top_sharp: topSharp,
          };
          lastVariablesRef.current = {
            y_position: yPosition,
            top_sharp: topSharp,
          };
          hasVariableTargetsRef.current = true;
        }
      }
    } catch (error) {
      hasVariableTargetsRef.current = false;
      if (import.meta.env.DEV) {
        console.warn("[Orb] Unable to read Spline variables", error);
      }
    }

    setIsSplineReady(true);
    setAvailableObjects(spline.getAllObjects().map((object) => object.name));
    registerReactiveObjects(spline);

    window.setTimeout(() => {
      registerReactiveObjects(spline);
    }, 600);
  }, [registerReactiveObjects]);

  useEffect(() => () => {
    cancelAnimationFrame(frameRef.current ?? 0);
    cleanupAudio();
  }, [cleanupAudio]);

  useEffect(() => {
    const spline = splineAppRef.current;
    if (!spline || reactiveObjectsRef.current.length === 0) {
      return () => undefined;
    }

    const activeAnalyser = analyser;
    const buffer = activeAnalyser ? new Uint8Array(activeAnalyser.frequencyBinCount) : null;
    const EPSILON = 0.0001;
    const MIN_SCALE_FACTOR = 0.65;
    const BASE_ROTATION_DRIFT = 0.45;

    const animate = () => {
      const time = performance.now() * 0.001;
      let smoothedBass = bassEnergyRef.current;
      let smoothedTreble = trebleEnergyRef.current;

      if (activeAnalyser && buffer && isPlaying) {
        activeAnalyser.getByteFrequencyData(buffer);
        const bassBinEnd = Math.max(4, Math.floor(buffer.length * 0.08));
        const highStart = Math.floor(buffer.length * 0.25);
        const highEnd = Math.floor(buffer.length * 0.9);

        let bassAggregate = 0;
        let highAggregate = 0;
        let highCount = 0;

        for (let i = 0; i < buffer.length; i += 1) {
          const value = buffer[i] / 255;
          if (i < bassBinEnd) {
            bassAggregate += value;
          }

          if (i >= highStart && i < highEnd) {
            highAggregate += value;
            highCount += 1;
          }
        }

        const bassAverage = bassAggregate / bassBinEnd;
        const highAverage = highCount > 0 ? highAggregate / highCount : 0;

        bassHistoryRef.current.unshift(bassAverage);
        trebleHistoryRef.current.unshift(highAverage);

        if (bassHistoryRef.current.length > 24) {
          bassHistoryRef.current.length = 24;
        }

        if (trebleHistoryRef.current.length > 24) {
          trebleHistoryRef.current.length = 24;
        }

        const bassRms = Math.sqrt(
          bassHistoryRef.current.reduce((sum, value) => sum + value * value, 0) /
            Math.max(1, bassHistoryRef.current.length)
        );

        const trebleRms = Math.sqrt(
          trebleHistoryRef.current.reduce((sum, value) => sum + value * value, 0) /
            Math.max(1, trebleHistoryRef.current.length)
        );

        const bassGain = bassRms > 0.001 ? 1 / bassRms : 1;
        const trebleGain = trebleRms > 0.001 ? 1 / trebleRms : 1;

        const normalizedBass = Math.min(1, bassAverage * bassGain * 0.85);
        const normalizedHigh = Math.min(1, highAverage * trebleGain * 0.9);

        smoothedBass = smoothedBass * 0.6 + normalizedBass * 0.4;
        smoothedTreble = smoothedTreble * 0.6 + normalizedHigh * 0.4;
      } else {
        bassHistoryRef.current.length = 0;
        trebleHistoryRef.current.length = 0;
        smoothedBass = bassEnergyRef.current * 0.85;
        smoothedTreble = trebleEnergyRef.current * 0.85;
      }

      bassEnergyRef.current = smoothedBass;
      trebleEnergyRef.current = smoothedTreble;

      if (hasVariableTargetsRef.current) {
        const baseVariables = baseVariableRef.current;
        const bassAmplitude = isPlaying ? Math.max(0, smoothedBass - 0.02) : 0;
        const easedAmplitude = Math.min(1, bassAmplitude * 2.8);

        const yBase = baseVariables.y_position;
        const ySwing = Math.max(10, Math.abs(yBase) * 0.25);
        const nextYPosition = isPlaying ? yBase + easedAmplitude * ySwing : yBase;

        const topSharpMax = 200;
        const trebleNormalized = isPlaying
          ? Math.pow(Math.min(1, Math.max(0, smoothedTreble)), 0.8)
          : Math.pow(Math.min(1, Math.max(0, baseVariables.top_sharp / topSharpMax)), 0.8);
        const targetTopSharp = isPlaying ? Math.max(5, trebleNormalized * topSharpMax) : baseVariables.top_sharp;

        const previous = lastVariablesRef.current;
        const dampedY = previous.y_position * 0.4 + nextYPosition * 0.6;
        const dampedTopSharp = previous.top_sharp * 0.4 + targetTopSharp * 0.6;

        const hasChanged =
          Math.abs(previous.y_position - dampedY) > 0.05 ||
          Math.abs(previous.top_sharp - dampedTopSharp) > 0.4;

        if (hasChanged) {
          spline.setVariables?.({
            y_position: dampedY,
            top_sharp: dampedTopSharp,
          });
          lastVariablesRef.current = {
            y_position: dampedY,
            top_sharp: dampedTopSharp,
          };
        }
      }

      reactiveObjectsRef.current.forEach((object) => {
        const baseScale = baseScaleRef.current.get(object.uuid);
        const baseRotation = baseRotationRef.current.get(object.uuid);

        if (!baseScale || !baseRotation) {
          return;
        }

        const isCalibrated = baseScale
          ? Math.abs(baseScale.x) > EPSILON || Math.abs(baseScale.y) > EPSILON || Math.abs(baseScale.z) > EPSILON
          : false;

        if (!isCalibrated) {
          if (Math.abs(object.scale.x) > EPSILON || Math.abs(object.scale.y) > EPSILON || Math.abs(object.scale.z) > EPSILON) {
            const safeScale = {
              x: Math.abs(object.scale.x) < EPSILON ? 1 : object.scale.x,
              y: Math.abs(object.scale.y) < EPSILON ? 1 : object.scale.y,
              z: Math.abs(object.scale.z) < EPSILON ? 1 : object.scale.z,
            };

            baseScaleRef.current.set(object.uuid, safeScale);
            baseRotationRef.current.set(object.uuid, { ...object.rotation });
            basePositionRef.current.set(object.uuid, { ...object.position });
          }
          return;
        }

        const bassLift = Math.max(0, smoothedBass - 0.08);
        const horizontalGain = Math.max(MIN_SCALE_FACTOR, 1 + bassLift * 1.6);
        const verticalGain = Math.max(MIN_SCALE_FACTOR, 1 + bassLift * 4.5);

        const safeScale = {
          x: Math.abs(baseScale.x) < EPSILON ? 1 : baseScale.x,
          y: Math.abs(baseScale.y) < EPSILON ? 1 : baseScale.y,
          z: Math.abs(baseScale.z) < EPSILON ? 1 : baseScale.z,
        };

        const nextScale = {
          x: safeScale.x * horizontalGain,
          y: safeScale.y * verticalGain,
          z: safeScale.z * horizontalGain,
        };

        object.scale = nextScale;
        object.visible = true;
        object.show?.();

        const basePosition = basePositionRef.current.get(object.uuid);
        if (basePosition) {
          object.position = {
            x: basePosition.x,
            y: basePosition.y + safeScale.y * (verticalGain - 1) * 0.5,
            z: basePosition.z,
          };
        }

        const wobble = Math.sin(time * 1.6) * bassLift * 0.8;
        object.rotation = {
          x: baseRotation.x + wobble * 0.55,
          y: baseRotation.y + time * BASE_ROTATION_DRIFT,
          z: baseRotation.z + wobble * 0.42,
        };
      });

      spline.requestRender();
      frameRef.current = requestAnimationFrame(animate);
    };

    frameRef.current = requestAnimationFrame(animate);

    return () => {
      if (frameRef.current) {
        cancelAnimationFrame(frameRef.current);
      }

      if (hasVariableTargetsRef.current) {
        const baseVariables = baseVariableRef.current;
        spline.setVariables?.({
          y_position: baseVariables.y_position,
          top_sharp: baseVariables.top_sharp,
        });
      }
    };
  }, [analyser, objectsVersion, isPlaying]);

  const showMissingTargetsMessage = isSplineReady && !hasReactiveTargets;
  const overlayMessage = audioError ?? null;

  const formatTime = (seconds: number) => {
    if (!Number.isFinite(seconds) || seconds < 0) {
      return "0:00";
    }

    const minutes = Math.floor(seconds / 60);
    const remaining = Math.floor(seconds % 60);
    return `${minutes}:${remaining.toString().padStart(2, "0")}`;
  };

  return (
    <div className={`relative w-full h-full ${className}`}>
      <Suspense
        fallback={
          <div className="flex h-full w-full items-center justify-center">
            <div className="h-32 w-32 animate-spin rounded-full border-b-2 border-white" />
          </div>
        }
      >
        <Spline scene="/scene.splinecode" wasmPath="/" onLoad={handleSplineLoad} />
      </Suspense>

      <div className="pointer-events-none absolute inset-0 flex flex-col items-end justify-end gap-2 p-6 text-xs text-white/80">
        <div className="pointer-events-auto flex w-full max-w-xs flex-col items-stretch gap-2 rounded-xl bg-black/35 p-3 backdrop-blur">
          <div className="flex items-center justify-between text-[11px] uppercase tracking-widest text-white/60">
            <span>Now Playing</span>
            <span>{isPlaying ? "Playing" : audioStatus === "loading" ? "Loading" : "Paused"}</span>
          </div>
          <button
            type="button"
            onClick={handleTogglePlayback}
            className="rounded-full bg-white/10 px-4 py-2 text-sm font-semibold text-white transition hover:bg-white/20"
          >
            {isPlaying ? "Pause" : audioStatus === "loading" ? "Loading…" : "Play"}
          </button>
          <div className="flex items-center justify-between text-[11px] text-white/70">
            <span>{formatTime(currentTime)}</span>
            <span>{formatTime(duration)}</span>
          </div>
          <div className="h-1 w-full overflow-hidden rounded-full bg-white/10">
            <div
              className="h-full bg-white/80 transition-all"
              style={{ width: duration > 0 ? `${Math.min(100, (currentTime / duration) * 100)}%` : "0%" }}
            />
          </div>
        </div>

        {(overlayMessage || (showMissingTargetsMessage && import.meta.env.DEV)) && (
          <div className="pointer-events-auto rounded-lg bg-black/40 px-3 py-2 text-[11px] leading-tight backdrop-blur">
            {overlayMessage ?? "No matching Spline objects for audio reactivity. See console for available names."}
          </div>
        )}

        {import.meta.env.DEV && availableObjects.length > 0 && (
          <details className="pointer-events-auto max-w-xs rounded-lg bg-black/25 px-3 py-2">
            <summary className="cursor-pointer text-[11px] font-semibold uppercase tracking-widest text-white/60">
              Spline Objects
            </summary>
            <ul className="mt-1 max-h-32 overflow-y-auto text-[11px] leading-tight">
              {availableObjects.map((name, index) => (
                <li key={`${name}-${index}`}>{name || "<untitled>"}</li>
              ))}
            </ul>
          </details>
        )}
      </div>
    </div>
  );
};

export default Orb;
